Lemma sh_shb : forall a, sh a = a / 8 + SHBASE.
Proof. intros a. unfold sh. rewrite Z.add_comm. reflexivity. Qed.

Lemma le4_sxw : forall k, word_to_le_bytes 4 (sxw k) = word_to_le_bytes 4 (Z_to_bv 64 k).
Proof. intros k. unfold sxw. exact (word_to_le_bytes_swrap 4%N k ltac:(lia)). Qed.

Lemma ck_align4 : forall M E e a, edenot E e = Z_to_bv 64 a -> 0 <= a < 2 ^ 64 -> a mod 4 = 0 ->
  sc_denot ASEGS M E (SCBr false BC_NE (EAlu ALU_AND e (ELit 3)) (ELit 0)).
Proof.
  intros M E e a He Ha Hal. cbn [sc_denot]. cbn [edenot]. rewrite He. rewrite w_and by lia.
  replace (Z.land a 3) with (a mod 4) by (change 3 with (Z.ones 2); rewrite Z.land_ones by lia; reflexivity).
  rewrite Hal. reflexivity.
Qed.

Ltac nd_sc CT CK DT DK DW :=
  lazymatch goal with
  | |- sc_denot _ _ _ (SCFlat (SA (EAlu ALU_SRL _ _) _) _) => clear DT DK DW; sc_shdj
  | |- sc_denot _ _ _ (SCFlat _ _) => clear DT DK DW; sc_fl
  | |- sc_denot _ _ _ (SCDisj (SA (EAlu ALU_SRL _ _) _) _ _ _) => clear DT DK; sc_shdj
  | |- sc_denot _ _ _ (SCDisj _ _ (SA (EAlu ALU_SRL _ _) _) _) => clear DT DK; sc_shdj
  | |- sc_denot _ _ _ (SCDisj _ _ _ _) => clear DW; sc_dj
  | |- sc_denot _ _ _ (SCReadBase _ _ false _) =>
      clear DT DK DW; eapply (sc_read_cellw _ _ _ _ _ _ _ _ CT);
      [cbn; lia | evs; rewrite ?v_addi_Z by lia; first [reflexivity | f_equal; lia] | evs; reflexivity]
  | |- sc_denot _ _ _ (SCReadBase _ _ true _) =>
      clear DT DK DW; eapply (sc_read_cell4_sx _ _ _ _ _ _ _ CK);
      [evs; rewrite ?v_addi_Z by lia; first [reflexivity | f_equal; lia] | evs; reflexivity]
  | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_AND _ (ELit 7)) _) =>
      clear DT DK DW; eapply ck_align; [evs; reflexivity | lia | Z.div_mod_to_equations; lia]
  | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_AND _ (ELit 3)) _) =>
      clear DT DK DW; eapply ck_align4; [evs; reflexivity | lia | lia]
  | |- sc_denot _ _ _ (SCBr false BC_EQ _ (ELit 0)) => clear DT DK DW; eapply ck_null; [evs; reflexivity | lia]
  | |- sc_denot _ _ _ (SCBr true _ _ _) => clear DT DK DW; sc_slow
  end.

Ltac rwc_newT Hlf WR fin :=
  lazymatch goal with |- rw_cells _ (mem_denot ?E ?m ?lg) ?A [?c] =>
    let rec go pre post :=
      lazymatch post with
      | SE ?a ?w ?v :: ?post' =>
          first [ eapply (rw_cells_mem_denot_w E m pre a w v post' A c);
                  [ exact Hlf
                  | repeat (apply Forall_cons; [cbn [e_addr e_width]; rwc_norm|]); apply Forall_nil
                  | rwc_norm
                  | exact WR | reflexivity | exact I | fin ]
                | let pre' := eval cbn [app] in (pre ++ [SE a w v]) in go pre' post' ]
      end in
    go (@nil sentry) lg
  end.

