  Lemma acr_mono : forall LB LB' SP SP' a n, aclient_range H LB SP a n -> (forall b, In b LB -> In b LB') -> SP' <= SP ->
    aclient_range H LB' SP' a n.
  Proof.
    intros LB LB' SP SP' a n A HI HS. unfold aclient_range in *.
    destruct A as [A|[A|[(b & Hb & A)|[(b & Hb & A)|A]]]].
    - left. lia.
    - right; left. exact A.
    - right; right; left. exists b. split; [exact (HI b Hb) | exact A].
    - right; right; right; left. exists b. split; [exact (HI b Hb) | exact A].
    - right; right; right; right. exact A.
  Qed.

  Lemma xc_of_acr : forall LB SP a n i, aclient_range H LB SP a n -> 0 <= i < n -> xclient H LB SP [] (a + i).
  Proof. intros LB SP a n i A Hi. split; [eapply aclient_range_addr; [exact A | lia] | intros K; exact K]. Qed.

  Lemma acr_pos : forall s LB m SP a n, as_RHEAP H s LB m -> 0 < SP -> 0 < n -> aclient_range H LB SP a n -> 0 < a.
  Proof.
    intros s LB m SP a n RH HSP Hn A.
    pose proof (ah_fsb H HH _ _ _ RH) as (FB1 & _ & _ & _). unfold AIMG_TOP in FB1.
    pose proof (aceil_facts) as ((ACF1 & _) & _ & _).
    destruct A as [A|[A|[(b & Hb & A)|[(b & Hb & A)|[A|[A|A]]]]]].
    - lia.
    - specialize (A a ltac:(lia)). unfold aimg_client in A. lia.
    - pose proof (ah_blocks H HH s LB m b RH Hb) as (B0 & _). lia.
    - pose proof (ah_blocks H HH s LB m b RH Hb) as (B0 & _). rewrite sh_shb in A.
      pose proof (Z.div_pos (blk_addr b) 8 ltac:(lia) ltac:(lia)). unfold SHBASE in A. lia.
    - lia.
    - rewrite sh_shb in A. pose proof (Z.div_pos (as_FSB H) 8 ltac:(lia) ltac:(lia)). unfold SHBASE in A. lia.
    - rewrite sh_shb in A. assert (0 <= aceil / 8) by (apply Z.div_pos; lia). unfold SHBASE in A. lia.
  Qed.

  Lemma shk_xp : forall LBk SP m m' x n k, xpres H LBk SP [] m m' -> shk m x k -> aclient_range H LBk SP (sh x) (nsh n) ->
    0 < n -> 0 <= x < 2 ^ 47 -> 0 <= k < 256 -> shk m' x k.
  Proof.
    intros LBk SP m m' x n k XP Hs A Hn Hx Hk.
    pose proof (div8_bound x Hx) as D.
    assert (C : cellw ASEGS m (x / 8 + SHBASE) 1 k).
    { split; [change (2 ^ (8 * Z.of_N 1)) with 256; lia|]. change (N.to_nat 1) with 1%nat.
      rewrite word_to_le_bytes_1 by lia. exact Hs. }
    assert (C' : cellw ASEGS m' (x / 8 + SHBASE) 1 k).
    { eapply (cellw_xp H); [exact XP | exact C | | |].
      - intros i Hi. change (Z.of_N 1) with 1 in Hi. replace (x / 8 + SHBASE + i) with (sh x + 0) by (rewrite sh_shb; lia).
        apply (xc_of_acr LBk SP (sh x) (nsh n) 0 A). unfold nsh. split; [lia|]. apply Z.div_str_pos. lia.
      - unfold SHBASE; lia.
      - change (Z.of_N 1) with 1. unfold SHBASE; lia. }
    destruct C' as [_ R1]. change (N.to_nat 1) with 1%nat in R1. rewrite word_to_le_bytes_1 in R1 by lia. exact R1.
  Qed.
End Fresh.

Definition srND : list expr := srs sr_id [(10%bv, EVar 32); (18%bv, EVar 33); (19%bv, ELit SHBASE)].
Definition SCR_NA := SCR [false; false; false] [EVar 34; EVar 35] [].
Definition SCR_NB := SCR [false; false; false; true; true] [EVar 34; EVar 35] [].
Definition KN_NA : list kentry := [KWr (SA (EVar 32) 0) (ELit 24)].
Definition KN_NB : list kentry := [KWr (SA (EVar 32) 0) (ELit 24); KWord (SA (EAlu ALU_SRL (EVar 34) (ELit 3)) SHBASE) 1 (EVar 36)].
Definition runNA :=
  Eval vm_compute in (sym_exec ASEGS 60 true [E_LF] SCR_NA (SS E_NEWRET srND [] (kn_fix 20 [E_LF] SCR_NA E_NEWRET srND KN_NA 50) 50) []).
Definition srNA' : list expr := Eval cbv in (let '(ss, _, _) := runNA in s_regs ss).
Definition lgNA : list sentry := Eval cbv in (let '(ss, _, _) := runNA in s_log ss).

Section EmpNd.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HHB : asan_rt_hyps_bp H.
  Let HH : asan_rt_hyps H := rt_bp_base H HHB.
  Hypothesis REH : reh_stmt H EMP_EXT.
  Variables (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (spz : Z).
  Variables (sk0 : as_St H) (LB0 : list block) (LF : list fframe) (obj bl bc key : Z) (ents : list (Z * (Z * Z))).
  Variables (lo B shi : Z) (m0 : mem) (mo0 : Model).
  Variables (tupp keyp2 : Z).

  Abbreviation LPREx := (LPRE H ra tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 spz sk0 LB0 LF obj bl bc key ents lo B shi m0 mo0).
  Abbreviation QIx := (QI H ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 spz sk0 LB0 LF obj bl bc key ents lo B shi m0 mo0).

  Definition NPRE (s : as_St H) (mo : Model) (m : mem) (errv : word) (LB LBm : list block) : Prop :=
    as_MPRES H mo0 mo
    /\ FRAME ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 spz m /\ spz mod 16 = 0 /\ 2 ^ 45 <= spf spz /\ spz <= 2 ^ 47
    /\ bv_unsigned ra mod 2 = 0
    /\ mem_inv asegs m /\ stk asegs m lo spz /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B
    /\ tp = Z_to_bv 64 ATP /\ aceil <= lo /\ lo <= spz - AEMP_STACK /\ spz <= shi /\ spz <= B /\ B < 2 ^ 64
    /\ map_live_frame LF obj /\ obj + 40 <= aceil
    /\ umapx MI_A 24 (nval24 ASEGS) (lbl LB) m obj bl bc ents /\ umap_sh m 24 (bl, bc, ents)
    /\ bc <> BSEQ_LAST /\ Zlength ents + 1 < 2 ^ 24 /\ 0 <= key < 2 ^ 32
    /\ addressable m obj 40 /\ wr_at asegs m obj 40
    /\ (forall b, In b LB -> obj + 40 <= blk_addr b \/ blk_addr b + blk_size b <= obj)
    /\ fldA m tupp 8 keyp2 /\ accessible m tupp 8 /\ emp_src H LB0 spz obj tupp 8 /\ tupp mod 8 = 0
    /\ fldA m keyp2 4 key /\ accessible m keyp2 4 /\ emp_src H LB0 spz obj keyp2 4 /\ keyp2 mod 4 = 0
    /\ as_RHEAP H s LB m /\ Permutation LB (LB0 ++ LBm) /\ Permutation (lbl LBm) (umap_blocks 24 bl bc ents)
    /\ lb_own LBm m
    /\ xpres H LB0 spz [(obj, obj + 40)] m0 m
    /\ as_RFS H LF m /\ ACONST m /\ stack0 m lo shi
    /\ as_AL H s >= as_AL H sk0 /\ 0 <= as_AL H s
    /\ lb_small LB + 24 + nsmall (8 * bseq_next bc) <= RT_SMALL_MAX /\ Z.of_nat (length LB) + 2 <= RT_CNT_MAX
    /\ nlarge LB + nlg (8 * bseq_next bc) <= RT_LARGE_MAX /\ ((bc = 0 \/ Zlength ents = bc) -> ICM (8 * bseq_next bc) <= as_AL H s)
    /\ trace_ok (as_TR H) APC0_FREE [emp_del_ra EMP_EXT].

  Lemma stage_node : forall (s : as_St H) (msF : machine_state) (mo : Model) (m : mem) (F : bvmap 5 word) (fc : bv 32)
      (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y24 y25 y26 y28 y29 y30 y31 : word) (errv : word) (LB LBm : list block),
    as_VIS H s msF = MS (mkR y1 (Z_to_bv 64 (spf spz)) gp tp y5 y6 y7 (Z_to_bv 64 obj) (Z_to_bv 64 (obj + 8)) y10 y11 y12 y13 y14
                             y15 y16 y17 (Z_to_bv 64 tupp) (Z_to_bv 64 SHBASE) (Z_to_bv 64 bc) (Z_to_bv 64 (obj / 8))
                             (Z_to_bv 64 key) (Z_to_bv 64 ((obj + 8) / 8 + SHBASE)) y24 y25 y26 s11 y28 y29 y30 y31)
                        F (Z_to_bv 64 E_NF) fc None m (seg_rom asegs) ->
    frm_zero fc -> as_AKREL H s (mkCfg msF mo) -> NPRE s mo m errv LB LBm ->
    (bc <> 0 -> y24 = Z_to_bv 64 (hmod key bc)) ->
    as_SR H QIx (mkCfg msF mo).
  Proof using All.
    intros s msF mo m F fc y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y24 y25 y26 y28 y29 y30 y31 errv LB LBm VIS FRZ KR NP HMOD.
    destruct NP as (MP & FR & SP16 & SPL & SPH & RAE & MI & ST & ERR & RA & TPV & ACL & LOR & SHI & SPB & BR & LFO & OCE
                    & U & SH & BCL & SZR & KR32 & AD & WR & OBL & FT & ACT & EST & TAL & FK & ACK & ESK & KAL
                    & RH & PE & PM & OWN & XP & RF & AC & S0 & AL & AL0 & RS & RC & RL & RICM & TRK).
    unfold spf in VIS, SPL.
    pose proof (aceil_facts) as ((ACF1 & ACF2) & _ & _).
    pose proof LOR as LOR'. unfold AEMP_STACK, AOPNEW_STACK, AMALLOC_STACK in LOR'.
    pose proof (u_obj_lo U) as Ho0. pose proof (u_obj_hi U) as Ho1. pose proof (u_obj_al U) as Hoal.
    pose proof (LbB_HFind.BSEQ_boundA bc (u_bseq U)) as BCR.
    destruct (bseq_next_factsE bc (u_bseq U) BCL) as (HnB & Hbcn & Hn28 & _).
    pose proof (LbB_HXmpD.obj_place H HH LF obj m RF LFO) as (VA & OB1 & OB2 & OB3). unfold AIMG_TOP in OB3.
    pose proof (ah_fsb H HH _ _ _ RH) as (FB1 & FB2 & FB3 & FB4).
    pose proof ACT as (AT0 & AT1 & _). pose proof ACK as (AK0 & AK1 & _). unfold AAPP_HI in AT1, AK1.
    assert (L0 : forall b, In b LB0 -> In b LB)
      by (intros b Hb; apply (Permutation_in _ (Permutation_sym PE)); apply in_or_app; left; exact Hb).
    assert (NS0 : 0 <= nsmall (8 * bseq_next bc)) by (unfold nsmall; destruct (_ <=? _); lia).
    assert (NL0 : 0 <= nlg (8 * bseq_next bc)) by (unfold nlg; destruct (_ <? _); lia).
    assert (KP0 : 0 < keyp2)
      by exact (acr_pos H HH s LB m spz keyp2 4 RH ltac:(lia) ltac:(lia) (acr_mono H LB0 LB spz spz keyp2 4 (proj1 ESK) L0 ltac:(lia))).
    destruct (src4_shk m keyp2 ACK KAL) as (k & SKm & KC).
    assert (KB : 0 <= k < 8) by (destruct KC as [KC|KC]; lia).
    assert (ST0m : sh0 m tupp) by exact (sh0_of_acc8 m tupp ACT TAL).
    assert (CT : cellw ASEGS m tupp 8 keyp2) by (split; [change (2 ^ (8 * Z.of_N 8)) with (2 ^ 64); lia | exact FT]).
    assert (CK : cell4 ASEGS m keyp2 key) by (split; [change (2 ^ (8 * Z.of_N 4)) with (2 ^ 32); lia | exact FK]).

    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose (E := Eseed R []).
    assert (HR : regs_ok E sr_id R) by apply regs_ok_seed.
    assert (HK : know_ok asegs E m []) by (unfold know_ok; apply Forall_nil).
    xrun_at (PropExec.mkFP F fc) asegs R E_NF m (seg_rom asegs) HR HK 20%nat [AOPNEW] (SCR [] [] []) 50%N.
    { split_scs. }
    try (lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) => change mm with m in Hms end).
    pose proof (msteps_full asegs _ _ Hms FHF) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rreg HR' 1%bv G1. rreg HR' 10%bv G10.
    change (getr R' 1%bv = Z_to_bv 64 E_NEWRET) in G1. change (getr R' 10%bv = Z_to_bv 64 24) in G10.
    rewrite G1, G10 in HRe.
    eapply (sr_blk_eq H HH); [exact KR | exact VIS | exact FHF | exact Hms | exact HRe |].
    intros msF1 mo1 KR1 MP1 VIS1.
    clear HRe HR' Hlf Hms HF1 G1 G10. clear R'.

    assert (AOK : as_alloc_ok H s LB 24).
    { apply (rt_bp_live H HHB s LB m 24 RH); [lia | change (nsmall 24) with 24; lia | lia | change (nlg 24) with 0; lia]. }
    assert (CM : as_Cm H 24 <= as_AL H s) by (rewrite (proj2 (rt_bp_cost H HHB) 24); change (ICM 24) with 0; lia).
    eapply (ah_seq H HH).
    { eapply (ah_opnew H HH) with (n := 24) (LB := LB) (lo := lo) (B := B) (errv := errv);
        [ exact VIS1 | exact RH | exact KR1 | exact AOK | exact CM | exact RA
        | rewrite u64_of_Z by lia; lia
        | rewrite u64_of_Z by lia; exact (proj1 (stk_split asegs m lo (spz - 96) spz ST ltac:(lia)))
        | exact ACL | rewrite u64_of_Z by lia; unfold AOPNEW_STACK, AMALLOC_STACK; lia
        | exact ERR | exact MI | exact TPV | rewrite u64_of_Z by lia; clear - SP16; Z.div_mod_to_equations; lia
        | exact AC | reflexivity | lia ]. }
    intros [msF2 mo2] POST.
    destruct POST as (t0' & t1' & t2' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m2 & errv2 & p & junk & pid & s'
                      & VIS2 & KR2 & MP2 & MI2 & ST2 & ERR2 & RA2 & AP2 & ABR & RH2 & CB2 & ADDR & AC2 & AL2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite (ret_pc_even E_NEWRET ltac:(unfold E_NEWRET; lia) eq_refl) in VIS2.
    rewrite u64_of_Z in AP2, ST2 by lia.
    rewrite (proj2 (rt_bp_cost H HHB) 24) in AL2. change (ICM 24) with 0 in AL2.
    pose proof ABR as (P0 & P16 & Pn & PI & PC & PF & PAPP). unfold AIMG_TOP in PI.
    assert (NI : ~ In pid (map blk_id LB)).
    { pose proof (ah_nodup H HH _ _ _ RH2) as ND. cbn [map] in ND. apply NoDup_cons_iff in ND. exact (proj1 ND). }

    assert (XP12 : xpres H LB (spz - 96) [] m m2) by exact (xpres_of_apres H _ _ [] _ _ AP2).
    assert (XP12s : xpres H LB spz [] m m2)
      by (eapply (xpres_weaken H); [exact XP12 | lia | intros b Hb; exact Hb | intros a Ha; exact Ha]).
    assert (FR2 : FRAME ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 spz m2)
      by (unfold FRAME, spf in FR |- *; eapply (apres_rw_cells H); [exact AP2 | exact FR | left; lia]).
    assert (ST2' : stk asegs m2 lo spz).
    { apply (stk_merge asegs m2 lo (spz - 96) spz); [exact ST2 | | lia].
      eapply (apres_stk H); [exact AP2 | exact (proj2 (stk_split asegs m lo (spz - 96) spz ST ltac:(lia))) | lia]. }
    assert (RF2 : as_RFS H LF m2) by exact (RFS_via_apres H HH LF LB _ m m2 RF AP2).
    assert (S02 : stack0 m2 lo shi) by (eapply (stack0_xpres H); [exact XP12 | exact S0 | apply Forall_nil]).
    assert (OWN2 : lb_own LBm m2).
    { eapply (lb_own_apres H); [exact OWN | exact AP2 |].
      intros b Hb. apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. exact Hb. }
    assert (ACRt : aclient_range H LB (spz - 96) tupp 8)
      by exact (acr_mono H LB0 LB spz (spz - 96) tupp 8 (proj1 EST) L0 ltac:(lia)).
    assert (ACRk : aclient_range H LB (spz - 96) keyp2 4)
      by exact (acr_mono H LB0 LB spz (spz - 96) keyp2 4 (proj1 ESK) L0 ltac:(lia)).
    assert (CT2 : cellw ASEGS m2 tupp 8 keyp2).
    { eapply (cellw_xp H); [exact XP12 | exact CT | | lia | change (Z.of_N 8) with 8; lia].
      intros i Hi. change (Z.of_N 8) with 8 in Hi. exact (xc_of_acr H LB (spz - 96) tupp 8 i ACRt ltac:(lia)). }
    assert (CK2 : cell4 ASEGS m2 keyp2 key).
    { unfold cell4 in CK |- *. eapply (cellw_xp H); [exact XP12 | exact CK | | lia | change (Z.of_N 4) with 4; lia].
      intros i Hi. change (Z.of_N 4) with 4 in Hi. exact (xc_of_acr H LB (spz - 96) keyp2 4 i ACRk ltac:(lia)). }
    assert (ST0 : sh0 m2 tupp).
    { unfold sh0 in ST0m |- *. eapply (shk_xp H LB (spz - 96) m m2 tupp 8 0); [exact XP12 | exact ST0m | | lia | lia | lia].
      exact (acr_mono H LB0 LB spz (spz - 96) (sh tupp) (nsh 8) (proj1 (proj2 EST)) L0 ltac:(lia)). }
    assert (SK2 : shk m2 keyp2 k).
    { eapply (shk_xp H LB (spz - 96) m m2 keyp2 4 k); [exact XP12 | exact SKm | | lia | lia | lia].
      exact (acr_mono H LB0 LB spz (spz - 96) (sh keyp2) (nsh 4) (proj1 (proj2 ESK)) L0 ltac:(lia)). }
    assert (WP2 : wr_at asegs m2 p 24) by exact (own_of_rw_cells m2 p 24 junk CB2 ltac:(lia)).
    assert (GZ2 : gz m2 p 24) by (intros i Hi; eapply sh0_of_addressable; [exact ADDR | change (8 * (24 / 8)) with 24; lia]).
    assert (ATP2 : apart tupp 8 p 24)
      by exact (aclient_range_apart_fresh H HH s' LB pid p 24 (spz - 96) m2 tupp 8 RH2 NI ltac:(lia) ltac:(lia) ACRt).
    assert (AKP2 : apart keyp2 4 p 24)
      by exact (aclient_range_apart_fresh H HH s' LB pid p 24 (spz - 96) m2 keyp2 4 RH2 NI ltac:(lia) ltac:(lia) ACRk).
    destruct (blk_win H HH LF s' ((pid, p, 24) :: LB) m2 pid p 24 p (p + 24) RH2 (or_introl eq_refl) ltac:(lia) ltac:(lia))
      as (W1 & W2 & W3 & W4 & W5).
    pose proof W5 as W5'. unfold ALOWSH_LO, AHI_LO in W5'.
    pose proof ATP2 as ATP2'. pose proof AKP2 as AKP2'. unfold apart in ATP2', AKP2'.

    lazymatch type of VIS2 with _ = MS ?T _ _ _ _ _ _ => remember T as R2 eqn:HR2 end.
    assert (FH2 : rfull R2) by (rewrite HR2; apply rfull_mkR).
    pose (E2 := Eseed R2 [Z_to_bv 64 p; Z_to_bv 64 tupp; Z_to_bv 64 keyp2; sxw key; Z_to_bv 64 k]).
    assert (HRb : regs_ok E2 srND R2).
    { unfold srND. apply regs_ok_srs; [apply regs_ok_seed|].
      repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R2; evs; reflexivity] |]).
      apply Forall_nil. }
    assert (RUN : exists R3, CatSim.msteps asegs (MS R2 F (Z_to_bv 64 E_NEWRET) fc None m2 (seg_rom asegs))
                                          (MS R3 F (Z_to_bv 64 E_LF) fc None (mem_denot E2 m2 lgNA) (seg_rom asegs))
                             /\ log_flat E2 lgNA /\ regs_ok E2 srNA' R3).
    { clear PF W5 RICM OBL HMOD. destruct KC as [K0|KNZ].
      - subst k.
        assert (HKb : know_ok asegs E2 m2 (kn_fix 20 [E_LF] SCR_NA E_NEWRET srND KN_NA 50)).
        { kn_eval. unfold know_ok.
          apply Forall_cons.
          { eapply kwr_of_wr_at; [exact WP2 | unfold estart; evs; rewrite u64_of_Z by lia; lia
                                 | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; lia
                                 | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
          know_tac. }
        xrun_at (PropExec.mkFP F fc) asegs R2 E_NEWRET m2 (seg_rom asegs) HRb HKb 60%nat [E_LF] SCR_NA 50%N.
        { split_scs. all: nd_sc CT2 CK2 ATP2' AKP2' W5'. }
        lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) => change mm with (mem_denot E2 m2 lgNA) in Hms end.
        change (log_flat E2 lgNA) in Hlf. change (regs_ok E2 srNA' R') in HR'.
        exists R'. split; [exact Hms | split; [exact Hlf | exact HR']].
      - assert (HKb : know_ok asegs E2 m2 (kn_fix 20 [E_LF] SCR_NB E_NEWRET srND KN_NB 50)).
        { kn_eval. unfold know_ok.
          apply Forall_cons.
          { eapply kwr_of_wr_at; [exact WP2 | unfold estart; evs; rewrite u64_of_Z by lia; lia
                                 | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; lia
                                 | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
          apply Forall_cons.
          { exact (kshadow E2 m2 (EVar 34) keyp2 k (EVar 36) ltac:(evs; reflexivity) ltac:(lia) ltac:(lia) ltac:(evs; reflexivity) SK2). }
          know_tac. }
        xrun_at (PropExec.mkFP F fc) asegs R2 E_NEWRET m2 (seg_rom asegs) HRb HKb 60%nat [E_LF] SCR_NB 50%N.
        { split_scs. all: nd_sc CT2 CK2 ATP2' AKP2' W5'. }
        lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) => change mm with (mem_denot E2 m2 lgNA) in Hms end.
        change (log_flat E2 lgNA) in Hlf. change (regs_ok E2 srNA' R') in HR'.
        exists R'. split; [exact Hms | split; [exact Hlf | exact HR']]. }
    destruct RUN as (R3 & Hms3 & Hlf3 & HR3).
    clear ATP2' AKP2' W5'.
    set (M3 := mem_denot E2 m2 lgNA) in Hms3.
    assert (MU3 : munch [(p, p + 24)] m2 M3).
    { subst M3. apply munch_mem_denot; [exact Hlf3|]. unfold lgNA.
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia;
                                  cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM3 : wmono asegs m2 M3) by (subst M3; apply wmono_mem_denot).
    assert (MI3 : mem_inv asegs M3) by exact (msteps_mem_inv asegs _ _ Hms3 MI2).
    assert (WRA : forall o w, 0 <= o -> o + w <= 24 -> 0 <= w -> wr_at asegs m2 (p + o) w)
      by (intros o w Ho Hw Hw0; eapply LbB_HXmpD.wr_at_subE; [exact WP2 | lia | lia | lia]).
    assert (WR0 : wr_at asegs m2 p 8) by (eapply LbB_HXmpD.wr_at_subE; [exact WP2 | lia | lia | lia]).
    assert (CN3 : rw_cells asegs M3 p [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 key); C4 (Z_to_bv 64 key); C4 (Z_to_bv 64 0)]).
    { apply cells4_join; subst M3; unfold lgNA.
      - rwc_newT Hlf3 WR0 ltac:(evs; reflexivity).
      - rwc_newT Hlf3 (WRA 8 8 ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(evs; rewrite HR2; reflexivity).
      - rwc_newT Hlf3 (WRA 16 4 ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(evs; rewrite le4_sxw; reflexivity).
      - rwc_newT Hlf3 (WRA 20 4 ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(evs; reflexivity). }
    pose proof (msteps_full asegs _ _ Hms3 FH2) as HF3. cbn [ms_regs] in HF3.
    readback HR3 HF3 HR2 HRe3.
    rreg HR3 10%bv G10. rreg HR3 19%bv G19. rreg HR3 25%bv G25.
    change (getr R3 19%bv = Z_to_bv 64 SHBASE) in G19. change (getr R3 25%bv = rShe (Z_to_bv 64 p)) in G25.
    rewrite G10, G19, G25 in HRe3.

    destruct (client_frame H HH s' ((pid, p, 24) :: LB) LF B [(p, p + 24)] m2 M3 RH2 RF2 AC2 RA2 MU3 WM3
               (Forall_cons _ _ _ W1 (Forall_nil _)) (Forall_cons _ _ _ W2 (Forall_nil _)) (Forall_cons _ _ _ W3 (Forall_nil _)))
      as (RH3 & RF3 & AC3 & RA3).
    assert (S03 : stack0 M3 lo shi)
      by (eapply stack0_transport; [exact S02 | exact MU3 | exact WM3 | exact (Forall_cons _ _ _ W4 (Forall_nil _))]).
    assert (ST3 : stk asegs M3 lo spz) by (subst M3; apply stk_mem_denot; exact ST2').
    assert (ERR3 : rw_cells asegs M3 (errno_addr tp) [C4 errv2]).
    { subst tp. unfold errno_addr in ERR2 |- *. rewrite u64_of_Z in ERR2 |- * by (unfold ATP; lia).
      eapply rw_cells_transport; [exact ERR2 | exact MU3 | exact WM3 | cbn; unfold ATP; lia]. }
    assert (FR3 : FRAME ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 spz M3).
    { unfold FRAME, spf in FR2 |- *. eapply rw_cells_transport; [exact FR2 | exact MU3 | exact WM3 |].
      cbn [disjoint_from]. split; [|exact I]. cbn [cells_size csize]. lia. }
    assert (XP23 : xpres H LB spz [] m2 M3).
    { eapply (xpres_munch_mixed H HH s' ((pid, p, 24) :: LB) LB [(pid, p, 24)] spz [] [(p, p + 24)] m2 m2 M3);
        [apply xpres_refl | exact RH2 | apply Permutation_cons_append | lia | exact MU3 | exact WM3 |].
      apply Forall_cons; [right; right; exists pid, p, 24; split; [left; reflexivity | cbn; lia] | apply Forall_nil]. }
    assert (XP03 : xpres H LB spz [] m M3) by (eapply (xpres_trans H); [exact XP12s | exact XP23]).
    assert (HOX : forall i, 0 <= i < 40 -> xclient H LB spz [] (obj + i)).
    { intros i Hi. split; [|intros K; exact K]. right; right; right; right; left. unfold AFS_SIZE in *. lia. }
    assert (INm : forall q k0, In (q, k0) (umap_blocks 24 bl bc ents) -> In (q, k0) (lbl LBm)).
    { intros q k0 Hq. apply (Permutation_in _ (Permutation_sym PM)). exact Hq. }
    assert (INL : forall q k0, In (q, k0) (lbl LBm) -> In (q, k0) (lbl LB)).
    { intros q k0 Hq. destruct (lbl_in_inv _ _ _ Hq) as (qi & Qi). unfold lbl. apply in_map_iff. exists (qi, q, k0).
      split; [reflexivity|]. apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. exact Qi. }
    assert (U3 : umapx MI_A 24 (nval24 ASEGS) (lbl ((pid, p, 24) :: LB)) M3 obj bl bc ents).
    { eapply (umapx_xp H 24 Z (nval24 ASEGS) LB spz [] LB ((pid, p, 24) :: LB) m M3 obj);
        [exact (nval24_agree ASEGS) | lia | exact XP03 | exact U | exact HOX |].
      apply (blkx_intro H). intros q k0 Hq. split; [exact (INL q k0 (INm q k0 Hq))|].
      split; [right; exact (INL q k0 (INm q k0 Hq)) | intros a _ K; exact K]. }
    assert (SH3 : umap_sh M3 24 (bl, bc, ents)).
    { eapply (umap_sh_xp H); [exact XP03 | exact SH |]. apply (blksh_intro H). intros q k0 Hq.
      split; [exact (INL q k0 (INm q k0 Hq)) | intros a _ K; exact K]. }
    assert (AD3 : addressable M3 obj 40).
    { eapply (addressable_xp H); [exact XP03 | exact AD |]. intros a Ha. split; [|intros K; exact K].
      right; right; right; right; right; left.
      unfold sh, nsh in Ha |- *. clear - Ha OB1 OB2 Hoal Ho0. Z.div_mod_to_equations. lia. }
    assert (WR3 : wr_at asegs M3 obj 40).
    { eapply xpres_wr_at; [exact XP03 | exact WR |].
      split; [right; right; right; right; left; unfold AFS_SIZE in *; lia | apply Forall_nil]. }
    assert (ADDR3 : addressable M3 p 24).
    { eapply addressable_transport_hi; [exact ADDR | exact MU3 | exact WM3 | unfold AAPP_HI; lia |].
      unfold wins_hi. apply Forall_cons; [|apply Forall_nil]. cbn [fst snd].
      destruct W5 as [X|X]; [left; split; [unfold AIMG_TOP; lia | exact X] | right; exact X]. }
    assert (OWN3 : lb_own ((pid, p, 24) :: LBm) M3).
    { apply (lb_own_wmono _ m2 M3); [|exact WM3]. unfold lb_own. apply Forall_cons; [exact WP2 | exact OWN2]. }

    eapply (sr_blk_eq H HH); [exact KR2 | exact VIS2 | exact FH2 | exact Hms3 | exact HRe3 |].
    intros msF3 mo3 KR3 MP3 VIS3.
    eapply (LbB_HXmpL.stage_lf H HH REH ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 spz sk0 LB0 LF obj bl bc key ents
              lo B shi m0 mo0 s' msF3 mo3 M3 F fc) with (errv' := errv2) (LB' := (pid, p, 24) :: LB) (LBm := (pid, p, 24) :: LBm) (p := p);
      [exact VIS3 | exact FRZ | exact KR3 | | exact HMOD].
    unfold LbB_HXmpL.LPRE.
    split; [eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | eapply (ah_mpres_trans H HH); [exact MP2 | exact MP3]]]|].
    split; [exact FR3|]. split; [exact SP16|]. split; [unfold spf; lia|]. split; [exact SPH|]. split; [exact RAE|].
    split; [exact MI3|]. split; [exact ST3|]. split; [exact ERR3|]. split; [exact RA3|].
    split; [exact TPV|]. split; [unfold spf; lia|]. split; [exact ACL|].
    split; [unfold spf, AREH_STACK, AOPNEW_STACK, AMALLOC_STACK; lia|].
    split; [exact SHI|]. split; [exact SPB|]. split; [exact BR|].
    split; [exact LFO|]. split; [exact OCE|].
    split; [exact U3|]. split; [exact SH3|].
    split; [exact BCL|]. split; [exact SZR|]. split; [exact KR32|].
    split; [exact AD3|]. split; [exact WR3|].
    split.
    { intros b [Hb|Hb]; [|exact (OBL b Hb)]. subst b.
      change (blk_addr (pid, p, 24)) with p. change (blk_size (pid, p, 24)) with 24. lia. }
    split; [lia|]. split; [lia|]. split; [exact P16|]. split; [unfold apart; lia|].
    split.
    { intros q n Hq. destruct (lbl_in_inv _ _ _ (INL q n (INm q n Hq))) as (qi & Qi).
      assert (NE : pid <> qi).
      { intros E0. apply NI. apply in_map_iff. exists (qi, q, n). split; [cbn; symmetry; exact E0 | exact Qi]. }
      pose proof (ah_disj H HH s' ((pid, p, 24) :: LB) m2 (pid, p, 24) (qi, q, n) RH2 (or_introl eq_refl) (or_intror Qi) NE) as D.
      cbn in D. unfold apart. lia. }
    split; [exact CN3|]. split; [exact ADDR3|].
    split; [exact RH3|].
    split; [eapply Permutation_trans; [apply perm_skip; exact PE | apply Permutation_middle]|].
    split; [change (lbl ((pid, p, 24) :: LBm)) with ((p, 24) :: lbl LBm); apply perm_skip; exact PM|].
    split; [exact OWN3|].
    split; [eapply (xpres_trans H); [exact XP | eapply (xpres_weaken H); [exact XP03 | lia | exact L0 | intros a Ha; destruct Ha]]|].
    split; [exact RF3|]. split; [exact AC3|]. split; [exact S03|].
    split; [lia|]. split; [lia|].
    split; [change (lb_small ((pid, p, 24) :: LB)) with (nsmall 24 + lb_small LB); change (nsmall 24) with 24; lia|].
    split; [cbn [length]; lia|].
    split; [change (nlarge ((pid, p, 24) :: LB)) with (nlg 24 + nlarge LB); change (nlg 24) with 0; lia|].
    split; [intros G; pose proof (RICM G); lia|].
    exact TRK.
  Qed.
End EmpNd.
